type SelectContext<T> = { value: T | null; setValue: (v: T) => void };
const Ctx = createContext<SelectContext<unknown> | null>(null);
export function useSelect<T>() {
  const ctx = useContext(Ctx) as SelectContext<T> | null;
  if (!ctx) throw new Error("Option must be rendered inside <Select>");
  return ctx;
}
export function Select<T>({ children }: { children: ReactNode }) {
  const [value, setValue] = useState<T | null>(null);
  return <Ctx.Provider value={{ value, setValue } as SelectContext<unknown>}>{children}</Ctx.Provider>;
}
Select.Option = Option;

