@Component({
  selector: "app-select",
  template: `<div role="listbox"><ng-content></ng-content></div>`,
  providers: [{ provide: SELECT_SCOPE, useExisting: forwardRef(() => SelectComponent) }],
})
export class SelectComponent {
  readonly options = contentChildren(OptionDirective);   // typed query
  private value = signal<string | null>(null);
  select(value: string) { this.value.set(value); }
}

@Directive({ selector: "[appOption]" })
export class OptionDirective {
  private scope = inject(SELECT_SCOPE);                  // parent via DI
  @HostListener("click") activate() { this.scope.select(this.value()); }
}

class SelectGroup extends HTMLElement {
  static formAssociated = true;
  #internals = this.attachInternals();
  connectedCallback() {
    this.attachShadow({ mode: "open" }).innerHTML = "<ul role='listbox'><slot></slot></ul>";
    this.shadowRoot!.querySelector("slot")!
        .addEventListener("slotchange", () => this.sync());
  }
  private sync(): void { /* re-derive from assignedElements() */ }
}

declare module "react" {                     // teach JSX the new tag
  namespace JSX { interface IntrinsicElements { "select-group": { children?: React.ReactNode } } }
}
customElements.define("select-group", SelectGroup);
